    input wire video_on,
    input wire [9:0] pixel_x,
    input wire [9:0] pixel_y,
    output reg [11:0] rgb_pic
);

    // Định nghĩa các hằng số màu sắc (12-bit RGB: 4-bit R, 4-bit G, 4-bit B)
    // Ví dụ: Background = Xanh dương đậm (00F), Wall = Trắng (FFF), Bar = Đỏ (F00), Ball = Xanh lá (0F0)
    parameter [11:0] COLOR_BG   = 12'h00F; // Background
    parameter [11:0] COLOR_WALL = 12'hFFF; // Wall
    parameter [11:0] COLOR_BAR  = 12'hF00; // Paddle / Bar
    parameter [11:0] COLOR_BALL = 12'h0F0; // Ball

    // Định nghĩa kích thước và vị trí các đối tượng trên màn hình (ví dụ VGA 640x480)
    // Wall: Cột bên trái từ x = 32 đến x = 47
    wire wall_region = (pixel_x >= 10'd32 && pixel_x <= 10'd47);

    // Bar (Thanh trượt): x từ 600 đến 615, y từ 200 đến 271 (chiều cao 72)
    wire bar_region = (pixel_x >= 10'd600 && pixel_x <= 10'd615) &&
                      (pixel_y >= 10'd200 && pixel_y <= 10'd271);

    // Ball (Bóng): hình vuông 8x8 tại vùng trung tâm giả định
    wire ball_region = (pixel_x >= 10'd320 && pixel_x <= 10'd327) &&
                       (pixel_y >= 10'd240 && pixel_y <= 10'd247);

    always @(*) begin
        if (!video_on) begin
            rgb_pic = 12'h000; // Tắt video hiển thị màu đen
        end else begin
            // Ưu tiên hiển thị: Ball -> Bar -> Wall -> Background
            if (ball_region) begin
                rgb_pic = COLOR_BALL;
            end else if (bar_region) begin
                rgb_pic = COLOR_BAR;
            end else if (wall_region) begin
                rgb_pic = COLOR_WALL;
            end else begin
                rgb_pic = COLOR_BG;
            end
        end
    end

endmodule
