    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            cnt   <= 8'd0;
        end else begin
            state <= next_state;
            cnt   <= next_cnt;
        end
    end

    // Khối tổ hợp: Logic chuyển trạng thái và tính toán bộ đếm
    always @(*) begin
        // Giá trị mặc định để tránh latch
        next_state  = state;
        next_cnt    = cnt;
        delayed_out = 1'b0;

        case (state)
