                    else begin
                        // Đang chạy, bật đèn
                        magnetron_on = 1'b1;

                        // Đếm ngược
                        if (time_left > 0) begin
                            next_time = time_left - 1'b1;
                            if (time_left == 8'd1) begin
                                next_state = IDLE;
                                bell_done  = 1'b1;
                            end
                        end else begin
                            next_state = IDLE;
                        end
                    end
                end

                default: begin
                    next_state = IDLE;
                end
            endcase
        end
    end

