module alu_4bit (
    input wire clk,
    input wire rst,
    input wire [3:0] a,
    input wire [3:0] b,
    input wire [2:0] opcode,
    output reg [3:0] alu_out,
    output reg zero,
    output reg carry
);

    // Các biến trung gian cho logic tổ hợp
    reg [3:0] next_alu_out;
    reg next_carry;
    reg [4:0] temp_arith; // Dùng 5 bit để bắt bit nhớ

    // Khối logic tổ hợp tính toán giá trị tiếp theo
    always @(*) begin
        // Giá trị mặc định để tránh latch
        next_alu_out = 4'b0000;
        next_carry = 1'b0;
        temp_arith = 5'b0;

        case (opcode)
            3'b000: begin // Cộng
                temp_arith = {1'b0, a} + {1'b0, b};
                next_alu_out = temp_arith[3:0];
                next_carry = temp_arith[4];
            end
            3'b001: begin // Trừ
                temp_arith = {1'b0, a} - {1'b0, b};
                next_alu_out = temp_arith[3:0];
                next_carry = temp_arith[4]; // Trong phép trừ, bit 4 là cờ mượn (borrow)
            end
            3'b010: begin // AND
                next_alu_out = a & b;
                next_carry = 1'b0;
            end
            3'b011: begin // OR
                next_alu_out = a | b;
                next_carry = 1'b0;
            end
            3'b100: begin // XOR
                next_alu_out = a ^ b;
                next_carry = 1'b0;
            end
            3'b101: begin // NOT
                next_alu_out = ~a;
                next_carry = 1'b0;
            end
            3'b110: begin // Dịch trái
                next_alu_out = a << 1;
                next_carry = a[3]; // Bit bị đẩy ra ngoài
            end
            3'b111: begin // So sánh bằng
                next_alu_out = (a == b) ? 4'b0001 : 4'b0000;
                next_carry = 1'b0;
            end
            default: begin
                next_alu_out = 4'b0000;
                next_carry = 1'b0;
            end
        endcase
    end

    // Khối tuần tự cập nhật thanh ghi đầu ra
    always @(posedge clk) begin
        if (rst) begin
            alu_out <= 4'b0000;
            carry   <= 1'b0;
            zero    <= 1'b1; // Kết quả 0 thì zero = 1
        end else begin
            alu_out <= next_alu_out;
            carry   <= next_carry;
            // Cập nhật cờ zero dựa trên kết quả mới
            zero    <= (next_alu_out == 4'b0000) ? 1'b1 : 1'b0;
        end
    end

