 * Module: sky130_fd_sc_hd__dlclkp_4
 * Description: Integrated Clock Gating (ICG) cell.
 * Fixed: Explicit latch behavior to satisfy IEEE 1364-2001 synthesis standards.
 * The latch is transparent when CLK is low, and holds state when CLK is high.
 */

module sky130_fd_sc_hd__dlclkp_4 (
    input  wire GATE,
    input  wire CLK,
    output wire GCLK
);

    // Internal signal for the latched gate control
    // We define this as a reg to hold the state of the latch
    reg latch_out;

    // Latch logic:
    // This block implements a negative-level sensitive latch.
    // When CLK is 0, latch_out follows GATE (transparent).
    // When CLK is 1, latch_out holds its previous value.
    // To satisfy synthesis tools, we explicitly define the behavior.
    always @(CLK or GATE or latch_out) begin
        if (!CLK) begin
            latch_out = GATE;
        end else begin
            latch_out = latch_out; // Explicitly hold the value
        end
    end

    // Gating logic:
    // AND the latched gate signal with the original clock.
    // This ensures the clock is only gated when it is low, preventing glitches.
    assign GCLK = CLK & latch_out;

