    input  wire        write_exist,
    input  wire [15:0] write_data,
    input  wire        read_init,
    input  wire        read_clear,
    output wire        read_exist,
    output reg  [15:0] read_data
);

    // Thông số FIFO: Depth = 16 (4-bit address)
    parameter ADDR_WIDTH = 4;
    parameter FIFO_DEPTH = 16;

    // Bộ nhớ Dual-Port (Inferred RAM)
    reg [15:0] mem [0:FIFO_DEPTH-1];

    // Con trỏ (Pointers) - Dùng binary để truy cập RAM, Gray để đồng bộ
    reg [ADDR_WIDTH:0] wptr, rptr;
    reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;

    // Thanh ghi đồng bộ (CDC)
    reg [ADDR_WIDTH:0] wptr_sync_r1, wptr_sync_r2; // wptr đồng bộ sang read_clk
    reg [ADDR_WIDTH:0] rptr_sync_w1, rptr_sync_w2; // rptr đồng bộ sang write_clk

    // --- Miền ghi (Write Domain) ---
    // Cập nhật wptr và ghi dữ liệu
    always @(posedge write_clk or posedge write_res) begin
        if (write_res) begin
            wptr <= 0;
            wptr_gray <= 0;
        end else if (write_exist) begin
            wptr <= wptr + 1;
            wptr_gray <= ((wptr + 1) >> 1) ^ (wptr + 1);
            mem[wptr[ADDR_WIDTH-1:0]] <= write_data;
        end
    end

    // Đồng bộ rptr sang miền ghi (để quản lý full flag nếu cần)
    always @(posedge write_clk or posedge write_res) begin
        if (write_res) begin
            rptr_sync_w1 <= 0;
            rptr_sync_w2 <= 0;
        end else begin
            rptr_sync_w1 <= rptr_gray;
            rptr_sync_w2 <= rptr_sync_w1;
        end
    end

    // --- Miền đọc (Read Domain) ---
    // Cập nhật rptr và đọc dữ liệu
    always @(posedge read_clk or posedge read_res) begin
        if (read_res || read_clear) begin
            rptr <= 0;
            rptr_gray <= 0;
            read_data <= 16'd0;
        end else if (read_init && (rptr != wptr_sync_r2)) begin
            rptr <= rptr + 1;
            rptr_gray <= ((rptr + 1) >> 1) ^ (rptr + 1);
            read_data <= mem[rptr[ADDR_WIDTH-1:0]];
        end else begin
            read_data <= read_data; // Giữ nguyên giá trị
        end
    end

    // Đồng bộ wptr sang miền đọc
    always @(posedge read_clk or posedge read_res) begin
        if (read_res) begin
            wptr_sync_r1 <= 0;
            wptr_sync_r2 <= 0;
        end else begin
            wptr_sync_r1 <= wptr_gray;
            wptr_sync_r2 <= wptr_sync_r1;
        end
    end

    // Logic read_exist: FIFO không rỗng khi con trỏ đọc khác con trỏ ghi (đã đồng bộ)
    // Chuyển đổi Gray sang Binary để so sánh chính xác
    wire [ADDR_WIDTH:0] wptr_sync_bin;
