        if (rst0_i) begin
            sel_sync0 <= 1'b0;
            en_sync0  <= 1'b0;
            sel_q0    <= 1'b0;
            en_q0     <= 1'b0;
        end else begin
            sel_sync0 <= select;
            sel_q0    <= sel_sync0;
            en_sync0  <= enable;
            en_q0     <= en_sync0;
