    always @(posedge clk_i or posedge rst_i) begin
        if (rst_i) begin
            state <= IDLE;
            A <= 32'h67452301;
            B <= 32'hEFCDAB89;
            C <= 32'h98BADCFE;
            D <= 32'h10325476;
            E <= 32'hC3D2E1F0;
            round_cnt <= 7'd0;
        end else begin
            state <= next_state;
            if (state == PROCESS) begin
                round_cnt <= round_cnt + 1'b1;
                // SHA-1 Round Logic (Simplified update)
                A <= (A << 5) + (B & C) + D + E + W[0]; // Simplified compression
                B <= A;
                C <= (B << 30);
                D <= C;
                E <= D;
            end
        end
