module isp_dpc (
    input wire pclk,
    input wire rst_n,
    input wire [7:0] threshold,
    input wire in_href,
    input wire in_vsync,
    input wire [7:0] in_raw,
    output reg out_href,
    output reg out_vsync,
    output reg [7:0] out_raw
);

    // Tham số giả định cho độ rộng ảnh (cần điều chỉnh theo thực tế)
    parameter IMG_WIDTH = 1920;

    // 1. Line Buffers (Sử dụng Shift Registers đơn giản hóa)
    // Cần 4 dòng để tạo cửa sổ 5x5
    reg [7:0] line1 [0:IMG_WIDTH-1];
    reg [7:0] line2 [0:IMG_WIDTH-1];
    reg [7:0] line3 [0:IMG_WIDTH-1];
    reg [7:0] line4 [0:IMG_WIDTH-1];

    // 2. Cửa sổ 5x5 (Pipeline registers)
    reg [7:0] win [0:4][0:4];
    integer r, c;

    // 3. Logic trễ tín hiệu đồng bộ (Latency = 4 dòng + 4 pixel)
    // Đơn giản hóa: trễ 5 chu kỳ clock cho ví dụ này
    reg [4:0] href_dly;
    reg [4:0] vsync_dly;

    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            href_dly <= 5'b0;
            vsync_dly <= 5'b0;
        end else begin
            href_dly <= {href_dly[3:0], in_href};
            vsync_dly <= {vsync_dly[3:0], in_vsync};
        end
    end

    // 4. Cập nhật cửa sổ 5x5
    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            for (r = 0; r < 5; r = r + 1) begin
                for (c = 0; c < 5; c = c + 1) begin
                    win[r][c] <= 8'd0;
                end
            end
        end else if (in_href) begin
            // Shift dữ liệu vào cửa sổ
            win[0][0] <= win[0][1]; win[0][1] <= win[0][2]; win[0][2] <= win[0][3]; win[0][3] <= win[0][4]; win[0][4] <= in_raw;
            // (Logic thực tế cần đọc từ Line Buffer tại đây)
        end
    end

    // 5. Logic Median Filter & DPC (Tổ hợp)
    reg [7:0] center_pixel;
    reg [7:0] median_val;
    reg [8:0] diff;

    always @(*) begin
        center_pixel = win[2][2];
        // Tính Median đơn giản (giả lập)
        median_val = (win[2][1] + win[2][3] + win[1][2] + win[3][2]) >> 2;

        // Tính sai biệt
        if (center_pixel > median_val)
            diff = center_pixel - median_val;
        else
            diff = median_val - center_pixel;

        // Quyết định DPC
        if (diff > threshold)
            out_raw = median_val;
        else
            out_raw = center_pixel;
    end

    // 6. Gán đầu ra
    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            out_href <= 1'b0;
            out_vsync <= 1'b0;
        end else begin
            out_href <= href_dly[4];
            out_vsync <= vsync_dly[4];
        end
    end

