    input wire clk,
    input wire rst,
    input wire [31:0] dat_i,
    input wire wr_en,
    input wire rd_en,
    input wire ssvga_en,
    output reg [7:0] dat_o,
    output wire full,
    output wire empty
);

    // Tham số cấu hình FIFO
    parameter DEPTH = 16;
    parameter PTR_WIDTH = 4; // log2(16)

    // Bộ nhớ đệm (Dual-port RAM behavior)
    reg [31:0] mem [0:DEPTH-1];

    // Con trỏ
    reg [PTR_WIDTH-1:0] wr_ptr;
    reg [PTR_WIDTH-1:0] rd_ptr;
    reg [1:0] byte_sel; // Chọn 1 trong 4 byte của 32-bit
    reg [PTR_WIDTH:0] count; // Bộ đếm số phần tử (để xác định full/empty)

    // Logic cờ trạng thái
    assign full  = (count == DEPTH);
    assign empty = (count == 0);

    // Khối tuần tự: Ghi dữ liệu và cập nhật con trỏ
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            wr_ptr   <= 0;
            rd_ptr   <= 0;
            byte_sel <= 0;
            count    <= 0;
            dat_o    <= 8'h00;
        end else if (ssvga_en) begin
            // Logic Ghi
            if (wr_en && !full) begin
                mem[wr_ptr] <= dat_i;
                wr_ptr      <= wr_ptr + 1'b1;
                count       <= count + 1'b1;
            end

            // Logic Đọc
            if (rd_en && !empty) begin
                // Xuất byte dựa trên byte_sel
                case (byte_sel)
                    2'b00: dat_o <= mem[rd_ptr][7:0];
                    2'b01: dat_o <= mem[rd_ptr][15:8];
                    2'b10: dat_o <= mem[rd_ptr][23:16];
                    2'b11: dat_o <= mem[rd_ptr][31:24];
                    default: dat_o <= 8'h00;
                endcase

                // Cập nhật con trỏ đọc và byte_sel
                if (byte_sel == 2'b11) begin
                    byte_sel <= 2'b00;
                    rd_ptr   <= rd_ptr + 1'b1;
                    count    <= count - 1'b1;
                end else begin
                    byte_sel <= byte_sel + 1'b1;
                end
            end
        end
    end

