    input wire [1:0] req,
    input wire clock,
    input wire reset,
    output reg [1:0] grant,
    output reg select,
    output reg valid
);

    // Định nghĩa trạng thái FSM
    parameter IDLE    = 2'b00;
    parameter GRANT_0 = 2'b01;
    parameter GRANT_1 = 2'b10;

    reg [1:0] current_state;
    reg [1:0] next_state;
    reg last_winner; // Lưu trữ người thắng cuộc trước đó để thực hiện Round-Robin

    // Khối logic tuần tự: Cập nhật trạng thái và last_winner
    always @(posedge clock or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            last_winner   <= 1'b0;
        end else if (enable) begin
            current_state <= next_state;
            if (current_state == GRANT_0) last_winner <= 1'b0;
            else if (current_state == GRANT_1) last_winner <= 1'b1;
        end else begin
            current_state <= IDLE;
        end
    end

    // Khối logic tổ hợp: Xác định trạng thái tiếp theo và đầu ra
    always @(*) begin
        // Giá trị mặc định để tránh Latch
        next_state = IDLE;
        grant      = 2'b00;
        select     = 1'b0;
        valid      = 1'b0;

        case (current_state)
            IDLE: begin
                if (req[0] && req[1]) begin
                    // Round-robin: Nếu trước đó là 1, giờ ưu tiên 0 và ngược lại
                    if (last_winner == 1'b1) begin
                        next_state = GRANT_0;
                    end else begin
                        next_state = GRANT_1;
                    end
                end else if (req[0]) begin
                    next_state = GRANT_0;
                end else if (req[1]) begin
                    next_state = GRANT_1;
                end else begin
                    next_state = IDLE;
                end
            end

            GRANT_0: begin
                grant  = 2'b01;
                select = 1'b0;
                valid  = 1'b1;
                next_state = IDLE;
            end

            GRANT_1: begin
                grant  = 2'b10;
                select = 1'b1;
                valid  = 1'b1;
                next_state = IDLE;
            end

            endcase
    end

endmodule
