    // Reset bat dong bo (Asynchronous Reset)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 2'b00;
        end else begin
            count <= count + 1'b1;
        end
    end

    // Giai ma to hop de tao ra 4 pha voi Duty Cycle 50%
    // clk_0:   High tai count 0, 1 (Tuong ung pha 0 do)
    // clk_90:  High tai count 1, 2 (Tre 1 chu ky clk = 90 do)
    // clk_180: High tai count 2, 3 (Tre 2 chu ky clk = 180 do)
    // clk_270: High tai count 3, 0 (Tre 3 chu ky clk = 270 do)

    assign clk_0   = (count == 2'b00 || count == 2'b01);
    assign clk_90  = (count == 2'b01 || count == 2'b10);
    assign clk_180 = (count == 2'b10 || count == 2'b11);
    assign clk_270 = (count == 2'b11 || count == 2'b00);

