    input wire EnableCrc,
    input wire Reset,
    input wire SyncResetCrc,
    input wire Clk,
    input wire [7:0] Crc,
    output reg [7:0] CrcOut
);

    // Internal signal for next state calculation
    reg [7:0] next_crc;
    wire feedback;

    // Feedback calculation: MSB of current CRC XOR with Data
    assign feedback = CrcOut[7] ^ Data;

    // Combinational logic to calculate next CRC state
    always @(*) begin
        if (SyncResetCrc) begin
            next_crc = 8'h00;
        end else if (EnableCrc) begin
            // Polynomial: x^8 + x^2 + x^1 + 1 (0x07)
            // Shift left and XOR with polynomial if feedback is 1
            next_crc = {CrcOut[6:0], 1'b0} ^ (feedback ? 8'h07 : 8'h00);
        end else begin
            // If not enabled, we treat 'Crc' input as a parallel load value
            // or hold current value. Here we implement parallel load.
            next_crc = Crc;
        end
    end

    // Sequential logic for register update
    always @(posedge Clk or posedge Reset) begin
        if (Reset) begin
            CrcOut <= 8'h00;
        end else begin
            CrcOut <= next_crc;
        end
    end

