// Standard: IEEE 1364-2001
// Description: Viterbi transmitter-receiver interface with conditional inversion

module viterbi_tx_rx (
    input  wire clk,
    input  wire rst,
    input  wire encoder_i,
    input  wire enable_encoder_i,
    output reg  decoder_o
);

    // Internal registers for encoder state (Shift Register)
    reg [1:0] shift_reg;

    // Internal registers for error counter
    reg [2:0] err_cnt;

    // Internal signals for encoded bits
    wire enc_bit_0;
    wire enc_bit_1;
    wire encoded_stream;
    wire inverted_stream;

    // 1. Convolutional Encoder Logic (Rate 1/2)
    // Polynomials: G0 = 1+D^2, G1 = 1+D+D^2 (simplified)
    assign enc_bit_0 = shift_reg[1] ^ shift_reg[0];
    assign enc_bit_1 = shift_reg[1];

    // Multiplexing the encoded stream (simplified serialization)
    assign encoded_stream = (err_cnt[0]) ? enc_bit_0 : enc_bit_1;

    // 2. Conditional Inversion Logic
    // Invert based on error counter reaching max value (7)
    assign inverted_stream = (err_cnt == 3'd7) ? ~encoded_stream : encoded_stream;

    // 3. Sequential Logic (Registers and Counters)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shift_reg <= 2'b00;
            err_cnt   <= 3'b000;
            decoder_o <= 1'b0;
        end else if (enable_encoder_i) begin
            // Shift in new data
            shift_reg <= {shift_reg[0], encoder_i};

            // Increment error counter
            err_cnt   <= err_cnt + 3'b001;

            // 4. Decoder Logic (Hard Decision)
            // Simple inverse mapping of the encoder
            decoder_o <= inverted_stream ^ shift_reg[1];
        end else begin
            // Maintain state if not enabled
            shift_reg <= shift_reg;
            err_cnt   <= err_cnt;
            decoder_o <= decoder_o;
        end
    end

