    input wire re,
    output reg [35:0] dout
);

    // Memory array: 4 entries of 36-bit
    reg [35:0] mem [0:3];

    // One-hot pointers: 4-bit wide
    reg [3:0] wr_ptr;
    reg [3:0] rd_ptr;

    // Write logic: Rotating one-hot pointer
    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= 4'b0001;
            for (i = 0; i < 4; i = i + 1) begin
                mem[i] <= 36'b0;
            end
        end else if (we) begin
            // Write data to current pointer position
            if (wr_ptr[0]) mem[0] <= din;
            if (wr_ptr[1]) mem[1] <= din;
            if (wr_ptr[2]) mem[2] <= din;
            if (wr_ptr[3]) mem[3] <= din;

            // Rotate pointer
            wr_ptr <= {wr_ptr[2:0], wr_ptr[3]};
        end
    end

    // Read logic: Rotating one-hot pointer
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rd_ptr <= 4'b0001;
