    // Note: In standard 2's complement subtraction A - B:
    // A - B = A + (~B + 1)
    // Here we implement: S = A + (~B) + c

    assign b_inverted = B ^ 4'b1111;
    assign result = A + b_inverted + {3'b000, c};

    // Assign the lower 4 bits to the output S
    assign S = result[3:0];

