    // Khai báo các tích riêng (partial products)
    wire p0, p1, p2, p3;

    // Tạo các tích riêng bằng cổng AND
    assign p0 = a[0] & b[0];
    assign p1 = a[1] & b[0];
    assign p2 = a[0] & b[1];
    assign p3 = a[1] & b[1];

    // Logic cộng các tích riêng
    // z[0] là bit thấp nhất, không có carry vào
    // z[1] là tổng của p1 và p2
    // z[2] là tổng của p3 và carry từ (p1+p2)
    // z[3] là carry từ (p3 + carry_p1_p2)

    reg [3:0] z_reg;

    always @(*) begin
        // Tính toán các bit trung gian
        // Half Adder cho p1 + p2
        // sum_1 = p1 ^ p2
        // carry_1 = p1 & p2

        // Bit 0: p0
        z_reg[0] = p0;

        // Bit 1: p1 ^ p2
        z_reg[1] = p1 ^ p2;

        // Bit 2: p3 ^ (p1 & p2)
        z_reg[2] = p3 ^ (p1 & p2);

        // Bit 3: p3 & (p1 & p2)
        z_reg[3] = p3 & (p1 & p2);
