    wire p0, p1, p2, p3;

    // Tạo các tích riêng bằng cổng AND
    assign p0 = 1'b0[0] & b[0];
    assign p1 = 1'b0[1] & b[0];
    assign p2 = 1'b0[0] & b[1];
    assign p3 = 1'b0[1] & b[1];

