module clk_divider_half (
    input  wire clk,
    input  wire rstn,
    output wire clk_div
);

    // Bộ đếm chạy trên cạnh lên của clk
    reg [2:0] cnt;
    reg clk_p;
    reg clk_n;

    // 1. Bộ đếm 0-6 (tổng 7 nửa chu kỳ)
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            cnt <= 3'b000;
        end else begin
            if (cnt == 3'd6)
                cnt <= 3'b000;
            else
                cnt <= cnt + 3'b001;
        end
    end

    // 2. Tạo tín hiệu clk_p (trên cạnh lên)
    // High khi cnt = 0, 1, 2
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            clk_p <= 1'b0;
        end else begin
            if (cnt == 3'd0)
                clk_p <= 1'b1;
            else if (cnt == 3'd3)
                clk_p <= 1'b0;
        end
    end

    // 3. Tạo tín hiệu clk_n (trên cạnh xuống)
    // High khi cnt = 0, 1, 2 (trễ pha nửa chu kỳ)
    always @(negedge clk or negedge rstn) begin
        if (!rstn) begin
            clk_n <= 1'b0;
        end else begin
            if (cnt == 3'd0)
                clk_n <= 1'b1;
            else if (cnt == 3'd3)
                clk_n <= 1'b0;
        end
    end

    // 4. Kết hợp để tạo xung chia 3.5
    // OR logic đảm bảo không có glitch
    assign clk_div = clk_p | clk_n;

endmodule
