    reg [9:0] v_cnt;

    // Horizontal Counter
    always @(posedge crt_clk or posedge rst) begin
        if (rst) begin
            h_cnt <= 10'd0;
        end else begin
            if (h_cnt == (H_TOTAL - 1))
                h_cnt <= 10'd0;
            else
                h_cnt <= h_cnt + 1'b1;
        end
    end

    // Vertical Counter
    always @(posedge crt_clk or posedge rst) begin
        if (rst) begin
            v_cnt <= 10'd0;
        end else begin
            if (h_cnt == (H_TOTAL - 1)) begin
                if (v_cnt == (V_TOTAL - 1))
                    v_cnt <= 10'd0;
                else
                    v_cnt <= v_cnt + 1'b1;
            end
        end
    end

    // Output Logic (Combinational logic registered for stability)
    always @(posedge crt_clk or posedge rst) begin
        if (rst) begin
            hsync  <= 1'b0;
            vsync  <= 1'b0;
            hblank <= 1'b1;
            vblank <= 1'b1;
