    always @(posedge clk_i or posedge rst_i) begin
        if (rst_i) begin
            state_r <= IDLE;
            count_r <= 3'd0;
            result_r <= 8'd0;
            busy_o <= 1'b0;
            y_bo <= 8'd0;
