    input  [3:0] a,
    input  [3:0] b,
    input        cin,
    output [3:0] sum,
    output       cout
);

    // Các tín hiệu trung gian cho Full Adder
    wire [3:0] p; // Propagate signals
    wire [3:0] g; // Generate signals
    wire [3:0] c; // Carry signals internal

    // Tính toán Propagate và Generate cho từng bit
    assign p = a ^ b;
    assign g = a & b;

    // Logic Carry Chain (Ripple Carry bên trong)
    // c[0] là carry vào bit 0
    // c[1] là carry vào bit 1, v.v.
    assign c[0] = cin;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & c[1]);
    assign c[3] = g[2] | (p[2] & c[2]);

    // Carry out của bit cuối cùng (bit 3)
    wire c_out_ripple;
    assign c_out_ripple = g[3] | (p[3] & c[3]);

    // Tính toán Sum
    assign sum[0] = p[0] ^ c[0];
    assign sum[1] = p[1] ^ c[1];
    assign sum[2] = p[2] ^ c[2];
    assign sum[3] = p[3] ^ c[3];

