    wire d_in;

    // Scan multiplexer logic: 
    // If SCE is high, select Scan Data (SCD). 
    // If SCE is low, select Functional Data (D).
    assign d_in = SCE ? SCD : D;

    // Sequential logic for D Flip-Flop with Asynchronous Set
    // Triggered on the rising edge of CLK or falling edge of SET_B
    always @(posedge CLK or negedge SET_B) begin
        if (SET_B == 1'b0) begin
            // Asynchronous Set: When SET_B is low, Q is forced to 1
            Q <= 1'b1;
        end else begin
            // Synchronous operation: Sample the selected input on CLK edge
            Q <= d_in;
        end
    end

    // Complementary output logic
    // Q_N is always the logical inverse of Q
    assign Q_N = ~Q;

