    // Tham số cấu hình cho hệ số chia lẻ (ví dụ: N = 3)
    // Để chia cho 3, bộ đếm chạy từ 0 đến 2 (WIDTH = 2 bits)
    parameter integer N = 3;
    parameter integer WIDTH = 2;

    reg [WIDTH-1:0] cnt_p;
    reg [WIDTH-1:0] cnt_n;
    reg             clk_p;
    reg             clk_n;

    // Bộ đếm và tín hiệu toggle theo cạnh lên của clk
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            cnt_p <= {WIDTH{1'b0}};
            clk_p <= 1'b0;
        end else begin
            if (cnt_p == N - 1) begin
                cnt_p <= {WIDTH{1'b0}};
                clk_p <= 1'b1;
            end else begin
                cnt_p <= cnt_p + 1'b1;
                if (cnt_p == (N >> 1))
                    clk_p <= 1'b0;
            end
        end
    end

    // Bộ đếm và tín hiệu toggle theo cạnh xuống của clk
    always @(negedge clk or negedge rstn) begin
        if (!rstn) begin
            cnt_n <= {WIDTH{1'b0}};
            clk_n <= 1'b0;
