module kogge_stone_16 (
    input  [15:0] in1,
    input  [15:0] in2,
    output [15:0] sum,
    output        cout
);

    // Level 0: Generate and Propagate
    wire [15:0] G0;
    wire [15:0] P0;

    assign G0 = in1 & in2;
    assign P0 = in1 ^ in2;

    // Khai báo các tín hiệu qua các stage của Kogge-Stone adder
    reg [15:0] g_st1, p_st1;
    reg [15:0] g_st2, p_st2;
    reg [15:0] g_st3, p_st3;
    reg [15:0] g_st4;
    reg [15:0] carries;

    integer j;
    always @(*) begin
        // Stage 1 (offset = 1)
        for (j = 0; j < 16; j = j + 1) begin
            if (j < 1) begin
                g_st1[j] = G0[j];
                p_st1[j] = P0[j];
            end else begin
                g_st1[j] = G0[j] | (P0[j] & G0[j-1]);
                p_st1[j] = P0[j] & P0[j-1];
            end
        end

        // Stage 2 (offset = 2)
        for (j = 0; j < 16; j = j + 1) begin
            if (j < 2) begin
                g_st2[j] = g_st1[j];
                p_st2[j] = p_st1[j];
            end else begin
                g_st2[j] = g_st1[j] | (p_st1[j] & g_st1[j-2]);
                p_st2[j] = p_st1[j] & p_st1[j-2];
            end
        end

        // Stage 3 (offset = 4)
        for (j = 0; j < 16; j = j + 1) begin
            if (j < 4) begin
                g_st3[j] = g_st2[j];
                p_st3[j] = p_st2[j];
            end else begin
                g_st3[j] = g_st2[j] | (p_st2[j] & g_st2[j-4]);
                p_st3[j] = p_st2[j] & p_st2[j-4];
            end
        end

        // Stage 4 (offset = 8)
        for (j = 0; j < 16; j = j + 1) begin
            if (j < 8) begin
                g_st4[j] = g_st3[j];
            end else begin
                g_st4[j] = g_st3[j] | (p_st3[j] & g_st3[j-8]);
