        // Carries computation: C[i] = g_st4[i-1], C[0] = 0
        carries[0] = 1'b0;
        for (j = 1; j < 16; j = j + 1) begin
            carries[j] = g_st4[j-1];
        end
    end

    // Gán đầu ra cuối cùng
    assign sum  = P0 ^ carries;
    assign cout = g_st4[15];

