);

    // Tách các trường từ toán hạng IEEE 754 32-bit
    wire        in_sign;
    wire [7:0]  in_exp;
    wire [22:0] in_frac;

    assign in_sign = opa[31];
    assign in_exp  = opa[30:23];
    assign in_frac = opa[22:0];

