    wire        hidden_bit;
    wire [23:0] computed_fracta;
    wire [7:0]  computed_exp;
    wire        computed_inf;
    wire [1:0]  computed_ovf;
    wire [2:0]  computed_und;

    // Xác định bit ẩn: 0 nếu số subnormal (in_exp == 0), ngược lại là 1
    assign hidden_bit = (in_exp != 8'h00);
    assign computed_fracta = {hidden_bit, in_frac};

    // Hiệu chỉnh phần mũ và phát hiện đặc biệt (Inf / NaN / Zero)
    assign computed_exp = in_exp;

    // Phát hiện Inf hoặc NaN (exp == 0xFF)
