module binary2bcd (
    input  wire        sys_clk,
    input  wire        sys_rst_n,
    input  wire [29:0] data,
    output reg  [35:0] bcd_data
);

    // FSM States
    parameter S_IDLE  = 1'b0;
    parameter S_SHIFT = 1'b1;

    reg       state, next_state;
    reg [5:0] count, next_count; 

    // Thanh ghi dịch chứa: [BCD (36 bits) | Binary (30 bits)] = 66 bits tổng cộng
    reg [65:0] shift_reg, next_shift_reg;
    reg [65:0] temp_reg;

    integer i;

    // Khối tuần tự
    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            state     <= S_IDLE;
            count     <= 6'd0;
            shift_reg <= 66'd0;
            bcd_data  <= 36'd0;
        end else begin
            state     <= next_state;
            count     <= next_count;
            shift_reg <= next_shift_reg;
            if (state == S_IDLE) begin
                bcd_data <= shift_reg[65:30];
            end
        end
    end

    // Khối tổ hợp cho FSM và thuật toán Double-Dabble (Triệt tiêu hoàn toàn Latch)
    always @(*) begin
        next_state     = state;
        next_count     = count;
        next_shift_reg = shift_reg;
        temp_reg       = shift_reg;

        case (state)
            S_IDLE: begin
                next_count     = 6'd0;
                next_shift_reg = {36'd0, data};
                next_state     = S_SHIFT;
            end

            S_SHIFT: begin
                if (count < 6'd30) begin
                    // Duyệt 9 nhóm BCD (từ MSB đến LSB của phần BCD: bits 65:30)
                    for (i = 0; i < 9; i = i + 1) begin
                        if (temp_reg[30 + (i*4) +: 4] > 4'd4) begin
                            temp_reg[30 + (i*4) +: 4] = temp_reg[30 + (i*4) +: 4] + 4'd3;
                        end else begin
                            temp_reg[30 + (i*4) +: 4] = temp_reg[30 + (i*4) +: 4];
                        end
