                    next_shift_reg = temp_reg << 1;
                    next_count     = count + 6'd1;
                    next_state     = S_SHIFT;
                end else begin
                    next_state     = S_IDLE;
                end
            end

            default: begin
                next_state     = S_IDLE;
                next_count     = 6'd0;
                next_shift_reg = {36'd0, data};
            end
        endcase
    end

