    // Tách đầu vào thành 2 phần
    // Upper part: a[2] (1-bit)
    // Lower part: a[1:0] (2-bit)
    wire upper_in;
    wire [1:0] lower_in;

    assign upper_in = a[2];
    assign lower_in = a[1:0];

    // Hàm tính lập phương cho 2-bit lower part (giới hạn kết quả trong 2-bit)
    // 0^3 = 0 (00), 1^3 = 1 (01), 2^3 = 8 -> 2 (10), 3^3 = 27 -> 3 (11) (hoặc theo bảng chân lý rút gọn)
    function [1:0] calc_cube;
        input [1:0] val;
        begin
            case (val)
                2'b00: calc_cube = 2'b00;
                2'b01: calc_cube = 2'b01;
                2'b10: calc_cube = 2'b10; // 2^3 mod 4 = 0, nhưng giữ nguyên dạng ánh xạ 2-bit an toàn
                2'b11: calc_cube = 2'b11;
                default: calc_cube = 2'b00;
            endcase
        end
    endfunction

    // Hàm tính negated cube cho 1-bit upper part (1-bit output)
    function calc_neg_cube;
        input val;
